// The scorer. State lives in nb; this cell is stateless and re-runnable.
function secretCode(seed) {
  let s = (Number(seed) * 2654435761) >>> 0;
  const code = [];
  for (let i = 0; i < 4; i++) { s = (1103515245 * s + 12345) >>> 0; code.push(s % 6); }
  return code;
}
function score(guess, code) {
  let black = 0;
  const gLeft = [], cLeft = [];
  for (let i = 0; i < 4; i++) {
    if (guess[i] === code[i]) black++;
    else { gLeft.push(guess[i]); cLeft.push(code[i]); }
  }
  let white = 0;
  for (const g of gLeft) {
    const idx = cLeft.indexOf(g);
    if (idx !== -1) { white++; cLeft.splice(idx, 1); }
  }
  return { black, white };
}

const NAMES = ['R', 'O', 'Y', 'G', 'B', 'P'];
const code = secretCode(nb.get('seed') ?? 3);
const guess = [nb.get('peg0'), nb.get('peg1'), nb.get('peg2'), nb.get('peg3')].map(Number);

const turn = nb.get('turn') ?? 0;
const lastScored = nb.get('last_scored') ?? 0;
let history = Array.isArray(nb.get('history')) ? nb.get('history') : [];

// Only record when a new Guess has been pressed since we last scored.
if (turn > lastScored) {
  const r = score(guess, code);
  history = [...history, { turn, guess: guess.map(i => NAMES[i]).join(' '), black: r.black, white: r.white }];
  nb.set('history', history);
  nb.set('last_scored', turn);
}

const latest = history[history.length - 1];
const solved = latest && latest.black === 4;
console.log('guess types (all numbers?):', guess.map(g => typeof g).join(', '));

return {
  solved: !!solved,
  message: solved ? `🎉 Cracked in ${history.length} guesses!`
                  : history.length ? `${latest.black}● ${latest.white}○ — keep going`
                                   : 'Set the pegs, press Guess, then run this cell.',
  history,
};

// Live values — proof the peg selects bind numbers (the coercion headline again).
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  peg0: val('peg0'),  // number 0..5 — a numeric select, not "0"
  peg1: val('peg1'),
  turn: val('turn'),  // number — the increment button's counter
  guessesRecorded: Array.isArray(nb.get('history')) ? nb.get('history').length : 0,
};
